const payload = $json.body ?? $json;
const minimumInfoFields = ['callerName', 'callerPhone', 'state', 'caseTypeBucket'];
const missingFields = minimumInfoFields.filter((f) => !payload[f]);
if (missingFields.length > 0) {
  return [{ json: { error: 'incomplete-minimum-info', missingFields, abort: true, nextAction: 'Re-prompt caller for missing fields before conflict check.' } }];
}
// Demo simulation: production calls firm CMS API. Demo branches on `simulateResult` field.
const simulateResult = `${payload.simulateResult ?? 'clear'}`.toLowerCase();
const opposingParties = Array.isArray(payload.opposingParties) ? payload.opposingParties : [];
let outcome;
if (simulateResult === 'conflict') outcome = 'conflict';
else if (simulateResult === 'manual-fallback') outcome = 'manual-fallback';
else outcome = 'clear';
const nextAction = {
  clear: 'Route to intake coordinator queue. CRM stage = conflict-cleared. Schedule callback within 4 business hours.',
  conflict: 'CRM stage = closed-conflict-declined. Send polite decline email. Do NOT collect more information. Do NOT explain conflict nature.',
  'manual-fallback': 'Pause workflow. Email intake coordinator with collected fields for manual conflict check.'
};
const leadId = `DEMO-LEGAL-${Date.now()}`;
return [{ json: { leadId, outcome, nextAction: nextAction[outcome], cmsApiCall: { endpoint: '[FIRM_CMS]_API_BASE_URL/matters/conflict-check', method: 'POST', payload: { callerName: payload.callerName, opposingParties, state: payload.state, caseTypeBucket: payload.caseTypeBucket } }, minimumInfo: { callerName: payload.callerName, callerPhone: payload.callerPhone, state: payload.state, caseTypeBucket: payload.caseTypeBucket, opposingParties }, factPatternCollected: false } }];
